import { isValidIsraeliCustomerPhone, mailingPhoneDigits } from "@/lib/mailing-source";

/** ספרות טלפון להתאמה ב־Firestore (אותו פורמט כמו בשדה `phone` של הזמנה) */
export function normalizeOrderPhoneForPush(phone: string | undefined | null): string | null {
  if (phone == null) return null;
  const d = mailingPhoneDigits(String(phone));
  if (!d) return null;
  if (!isValidIsraeliCustomerPhone(d)) return null;
  return d;
}

