export async function upsertFcmSubscription(
  db: Firestore,
  fcmToken: string,
  opts: { broadcastOptIn: boolean; addWatchOrderToken?: string },
): Promise<void> {
  const id = subscriptionDocIdForToken(fcmToken);
  const ref = db.collection(FCM_SUBSCRIPTIONS).doc(id);
  const now = new Date().toISOString();
  const snap = await ref.get();
  const addTok = opts.addWatchOrderToken?.trim();
  if (!snap.exists) {
    await ref.set({
      fcmToken,
      broadcastOptIn: opts.broadcastOptIn,
      watchOrderTokens: addTok ? [addTok] : [],
      createdAt: now,
      updatedAt: now,
    });
    return;
  }
